<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#1749b5"><title>Forgot seller password · EasyBuy</title><link rel="stylesheet" href="seller.css"><style>body{font-family:system-ui,sans-serif;background:#f4f7ff;color:#17213b}.recover-wrap{max-width:520px;margin:6vh auto;padding:20px}.recover-card{background:#fff;border-radius:18px;padding:28px;box-shadow:0 12px 36px #162c5818}.recover-card h1{margin-top:0}.recover-card label{display:block;font-weight:600;margin:15px 0}.recover-card input,.recover-card select{box-sizing:border-box;display:block;width:100%;padding:12px;border:1px solid #cbd5e1;border-radius:10px;margin-top:6px}.recover-card button{padding:12px 18px;border:0;border-radius:10px;background:#1749b5;color:white;font-weight:700;cursor:pointer;width:100%;margin-top:8px}.notice{margin-top:14px}.secure-note{background:#eff6ff;border:1px solid #bfdbfe;padding:12px;border-radius:10px;font-size:.92rem}.links{margin-top:18px}.links a{color:#1749b5}</style></head><body><main class="recover-wrap"><section class="recover-card"><p><a href="index.php">EasyBuy</a> / Seller Studio</p><h1>Forgot seller password?</h1><p>Answer the security question you selected when creating your seller account.</p><div class="secure-note"><strong>Note:</strong> Security answers can be guessed. Choose a hard-to-guess answer and never reuse public information.</div><form id="questionForm"><label>Registered seller email<input type="email" name="email" required autocomplete="email"></label><button type="submit">Find security question</button></form><form id="resetForm" hidden><p><strong id="questionText"></strong></p><label>Security answer<input name="security_answer" required maxlength="120" autocomplete="off"></label><label>New password (at least 8 characters)<input type="password" name="new_password" required minlength="8" autocomplete="new-password"></label><label>Confirm new password<input type="password" name="confirm_password" required minlength="8" autocomplete="new-password"></label><button type="submit">Verify answer & reset password</button></form><p id="notice" class="notice" role="status" aria-live="polite"></p><p class="links"><a href="sellerindex.php">← Back to seller login</a></p></section></main><script>
const qf=document.getElementById('questionForm'),rf=document.getElementById('resetForm'),notice=document.getElementById('notice');let resetEmail='';
async function send(action,values){const r=await fetch('api-seller-recover-password.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,...values})});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Request failed.');return d;}
qf.addEventListener('submit',async e=>{e.preventDefault();notice.textContent='';const b=qf.querySelector('button');b.disabled=true;resetEmail=new FormData(qf).get('email').trim();try{const d=await send('question',{email:resetEmail});document.getElementById('questionText').textContent=d.question;rf.hidden=false;qf.hidden=true;notice.textContent='Security question found. Enter your answer below.';}catch(err){notice.textContent=err.message;}finally{b.disabled=false;}});
rf.addEventListener('submit',async e=>{e.preventDefault();notice.textContent='';const values=Object.fromEntries(new FormData(rf).entries());if(values.new_password!==values.confirm_password){notice.textContent='Passwords do not match.';return;}const b=rf.querySelector('button');b.disabled=true;try{const d=await send('reset',{email:resetEmail,...values});notice.textContent=d.message;rf.reset();rf.hidden=true;qf.hidden=false;qf.reset();resetEmail='';}catch(err){notice.textContent=err.message;}finally{b.disabled=false;}});
</script></body></html>
